import { connectOnline } from './online.js';
import {createAudio} from './audio.js';
import {riverX,findRoute,routeLength} from './navigation.js';
import { freshGame, restoreGame, act, tick, income, power, totalTroops, costAt, canPay, BUILDINGS, UNITS, TECHS, RESOURCES } from './game.js';
import { createWorld } from './world.js';

const paths={
  crown:'M3 6l5 5 4-8 4 8 5-5-2 13H5L3 6ZM6 22h12',
  castle:'M3 21V9h5V4h3v4h2V4h3v5h5v12H3ZM6 9V6M18 9V6M9 21v-5a3 3 0 0 1 6 0v5M6 12v2M18 12v2',
  coins:'M16 5c0 2-3 3-7 3S2 7 2 5s3-3 7-3 7 1 7 3ZM2 5v5c0 2 3 3 7 3 1 0 2 0 3-.2M2 10v5c0 2 3 3 7 3m3-7c0-2 2-3 5-3s5 1 5 3-2 3-5 3-5-1-5-3Zm0 0v7c0 2 2 3 5 3s5-1 5-3v-7',
  tree:'M12 2 5 11h4l-5 7h6v4h4v-4h6l-5-7h4L12 2Z',
  mountain:'m2 20 7-14 4 7 3-10 7 17H2Zm5-10 2 2 2-2m3-1 2 2 2-2',
  wheat:'M12 22V3M12 8C7 8 5 5 6 2c4 0 6 2 6 6Zm0 5c-5 0-8-3-7-6 4 0 7 2 7 6Zm0 5c-5 0-8-3-7-6 4 0 7 2 7 6Zm0-8c5 0 8-3 7-6-4 0-7 2-7 6Zm0 6c5 0 8-3 7-6-4 0-7 2-7 6',
  swords:'m3 3 6 2 11 13-2 2L5 9 3 3Zm18 0-6 2-4 5M9 14l-5 6m-2-3 5 5m10-1 5-5',
  spear:'m5 21 13-15m-2-2 6-2-2 6-4-4ZM4 16l5 4',
  shield:'m12 2 9 4v6c0 5-4 8-9 10-5-2-9-5-9-10V6l9-4Zm0 4v12m-5-8h10',
  bow:'M5 3c15 0 15 18 0 18L17 12 5 3Zm-3 9h20m-4-3 4 3-4 3',
  horse:'M5 21h14v-4l-4-4 4-4-4-7-2 4-5 1-3 7 4 1 2-4 1 3-5 4-2 3ZM13 8h.1',
  siege:'M4 17h16M6 17l6-12 4 12M7 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm10 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4ZM9 5l10 5m-1-3 3-4',
  scroll:'M7 4h13v13H9M7 4a3 3 0 0 0-6 0v2h6V4Zm0 0v15a3 3 0 0 0 6 0v-2H9M11 8h6m-6 4h6',
  book:'M12 5C9 2 5 2 2 3v17c3-1 7-1 10 2 3-3 7-3 10-2V3c-3-1-7-1-10 2Zm0 0v17M5 7h3m-3 4h3m8-4h3m-3 4h3',
  flame:'M13 2c1 6-4 6-2 11 2-1 3-3 3-5 5 4 7 7 4 11-3 4-10 4-13 0-4-6 3-10 3-15 2 2 2 4 2 5 2-2 3-4 3-7Z',
  sun:'M16 12a4 4 0 1 0-8 0 4 4 0 0 0 8 0Zm-4-11v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',
  target:'M20 12a8 8 0 1 0-16 0 8 8 0 0 0 16 0ZM12 1v5m0 12v5M1 12h5m12 0h5M12 9v6m-3-3h6',
  layers:'m12 2 10 6-10 6L2 8l10-6ZM2 12l10 6 10-6M2 16l10 6 10-6',
  people:'M15 7a3 3 0 1 0-6 0 3 3 0 0 0 6 0ZM6 21v-4c0-7 12-7 12 0v4M4 5a3 3 0 0 0 0 6m16-6a3 3 0 0 1 0 6M2 14v6m20-6v6',
  arrow:'M4 12h16m-6-6 6 6-6 6',
};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.crown}"/></svg>`;
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=selector=>document.querySelector(selector);
const htmlCache=new WeakMap();function setHTML(el,html){if(htmlCache.get(el)!==html){el.innerHTML=html;htmlCache.set(el,html);}}
const format=n=>Math.floor(n).toLocaleString('ru-RU');
const resourceIcons={gold:'coins',wood:'tree',stone:'mountain',food:'wheat'};
const sound=createAudio();
const storageKey='kingdoms-save-v1';let saved=null;

let state=saved||freshGame(),selected='home',currentPanel=null,selectedFaction=null,recruitCount=5,unitFilter='Все',fraction=.75,world=null,previousFingerprint='',lastLog=state.logs[0]?.text;
const drawer=$('#drawer'),content=$('#drawer-content');
const titles={build:'Строительство',army:'Королевское войско',diplomacy:'Совет правителей',research:'Знания — сила державы',world:'События мира',log:'Летопись державы',help:'Первый день правления',goals:'Ваш путь к величию',march:'Военный поход',new:'Новая летопись',victory:'Королевство вошло в историю'};
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);});}
hydrateIcons();
function costs(cost){return `<div class="cost">${Object.entries(cost).map(([k,v])=>`<span title="${RESOURCES[k]}" data-cost-key="${k}" data-cost-value="${v}" class="${state.resources[k]<v?'short':''}">${icon(resourceIcons[k])}${format(v)}</span>`).join('')}</div>`;}
function toast(message,bad=false){const el=document.createElement('div');el.className=`toast${bad?' bad':''}`;el.textContent=message;$('#toasts').appendChild(el);setTimeout(()=>{el.classList.add('out');setTimeout(()=>el.remove(),220);},4200);}
async function perform(type,args){const r=await online.command(type,args);toast(r.message||'Готово',!r.ok);if(r.ok)sound.cue(type==='march'||type==='reinforce'?'march':type==='build'||type==='research'?'build':'click');return r;}
let saveFailed=false;
function save(){}
function selectPlace(id){selected=id;world?.select(id);updateSelection();drawMinimap();}
function openPanel(name,options={}){currentPanel=name;if(name==='diplomacy')selectedFaction=options.faction||null;if(name==='march')fraction=.5;renderPanel();if(!drawer.open)drawer.showModal();document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.panel===name));}
function closePanel(){drawer.close();currentPanel=null;document.querySelectorAll('.nav-button').forEach(b=>b.classList.remove('active'));}
function updateSelection(){const p=state.places.find(p=>p.id===selected),own=p.owner==='player',relation=state.relations[p.id];const rep=state.reputation>=75?'Почитаемый':state.reputation>=45?'Надёжный':state.reputation>=25?'Опасный':'Безжалостный';
  const html=`<div class="panel-kicker">${icon(own?'crown':p.kind==='camp'?'swords':'castle')}${(p.id===(state.home||'home')&&own)?'ВАШЕ КОРОЛЕВСТВО':own?'ВАШИ ВЛАДЕНИЯ':p.kind==='village'?'ВОЛЬНОЕ ПОСЕЛЕНИЕ':p.kind==='city'?'НЕЗАВИСИМАЯ ДЕРЖАВА':'ДИКИЕ ЗЕМЛИ'}</div><div class="settlement-title"><div class="settlement-crest" style="color:${p.color}">${icon(p.kind==='camp'?'swords':p.kind==='ruins'?'flame':'castle')}</div><div><h2>${p.name}</h2><p>${escape(p.ruler)}</p></div></div><div class="divider"></div>${(p.id===(state.home||'home')&&own)?`<div class="stat-line"><span>${icon('castle')}Владения</span><strong>${state.places.filter(p=>p.owner==='player').length} / ${state.places.length}</strong></div><div class="stat-line"><span>${icon('swords')}Гарнизон</span><strong>${totalTroops(state.troops)} воинов</strong></div><div class="stat-line"><span>${icon('shield')}Репутация</span><strong>${state.reputation} · ${rep}</strong></div><div class="rep-meter"><span style="width:${state.reputation}%"></span></div><button class="primary full" data-open="build">${icon('castle')}Развивать столицу</button><button class="sub-action" data-open="army">Управление войском →</button>`:`<p class="small-note">${p.detail}</p><div class="stat-line"><span>${icon('shield')}Оборона</span><strong>${format(p.defense)}</strong></div><div class="stat-line"><span>Отношения</span><strong>${own?'Ваше владение':relation?({peace:'Мир',alliance:'Союз',war:'Война',pact:'Договор'}[relation.status]):'Враждебные'}</strong></div>${own?`<div class="effect">+30 золота и +45 ${p.kind==='village'?'провизии':'камня'} / мин</div><p>Гарнизон: ${totalTroops(p.garrison||{})} воинов. Доход поступает автоматически. Строительство доступно в столице.</p><button class="primary full" data-open="march">Усилить гарнизон</button><button class="secondary full" data-recall="${p.id}" ${!totalTroops(p.garrison||{})?'disabled':''}>Вернуть гарнизон в столицу</button>`:`<button class="primary full" ${relation&&relation.status!=='war'?`data-negotiate="${p.id}"`:'data-open="march"'}>${icon(relation&&relation.status!=='war'?'scroll':'swords')}${relation&&relation.status!=='war'?'Начать переговоры':'Отправить войско'}</button>${relation?`<button class="sub-action" data-negotiate="${p.id}">Дипломатия и торговля →</button>`:''}`}`}`;
  setHTML($('#selection'),html);
}
function buildPanel(){return `<p class="intro">Развивайте свою столицу. Новые здания появятся на карте после завершения работы. Каждое здание можно улучшить до III уровня. Одновременно работает одна строительная бригада.</p><div class="card-grid">${Object.entries(BUILDINGS).map(([key,b])=>{const level=state.buildings[key],cost=costAt(b.cost,level),queued=state.queue.find(q=>q.type==='build'&&q.key===key);return `<article class="build-card"><div class="card-top"><span class="card-icon">${icon(b.icon)}</span><div><h3>${b.name}</h3><small>${level?'УРОВЕНЬ '+['','I','II','III'][level]:'НЕ ПОСТРОЕНО'}</small></div><span class="level-pips">${[1,2,3].map(i=>`<i class="${level>=i?'filled':''}"></i>`).join('')}</span></div><p>${b.text}</p><div class="effect">${b.effect}</div>${level<3?costs(cost):'<div class="effect">Максимальный уровень</div>'}<div class="card-footer"><small>${queued?'В работе':level<3?`${16+level*10} сек.`:'Улучшено полностью'}</small><button class="${level===0?'primary':'secondary'}" data-build="${key}" ${level>=3||state.queue.some(q=>q.type==='build')?'disabled':''}>${queued?'Строится…':level===0?'Построить':level===3?'Уровень III':'Улучшить'}</button></div></article>`;}).join('')}</div>`;}
function armyPanel(){const incoming=state.marches.reduce((n,m)=>n+totalTroops(m.troops),0);return `<div class="info-strip"><div><small>ГАРНИЗОН</small><strong>${totalTroops(state.troops)} <em>воинов</em></strong></div><div><small>СИЛА ВОЙСКА</small><strong>${power(state.troops,state)}</strong></div><div><small>В ПОХОДЕ</small><strong>${incoming}</strong></div></div><p class="intro">Нанимайте отряды и выбирайте цель на карте. Копейщики получают преимущество против северных рыцарей, осадные машины — против городов.</p><div class="inline-control"><span>Количество в отряде</span><select id="recruit-count" aria-label="Количество воинов для найма">${[5,10,20].map(n=>`<option value="${n}" ${recruitCount===n?'selected':''}>${n} воинов</option>`).join('')}</select></div><div class="tabs" aria-label="Типы войск">${['Все','Пехота','Стрелки','Кавалерия','Осада'].map(t=>`<button data-filter="${t}" class="${unitFilter===t?'active':''}">${t}</button>`).join('')}</div><div class="card-grid">${Object.entries(UNITS).filter(([,u])=>unitFilter==='Все'||u.type===unitFilter).map(([key,u])=>`<article class="unit-card"><div class="card-top"><span class="card-icon">${icon(u.icon)}</span><div><h3>${u.name}</h3><small>СИЛА ${u.power} · ${u.type.toUpperCase()}</small></div><div class="unit-count">${state.troops[key]||0}</div></div><p>${u.text}</p><div class="effect">${u.req>state.buildings.barracks?`Нужны казармы ${u.req} уровня`:`Отряд из ${recruitCount} воинов`}</div>${costs(costAt(u.cost,0,recruitCount))}<div class="card-footer"><small>${Math.ceil(Math.max(6,recruitCount*1.2/(1+state.buildings.barracks*.25)))} сек.</small><button class="secondary" data-recruit="${key}" ${u.req>state.buildings.barracks||state.queue.filter(q=>q.type==='recruit').length>=3?'disabled':''}>Нанять ${recruitCount}</button></div></article>`).join('')}</div><h3 class="section-title">ПОХОДЫ И ВОЗВРАЩЕНИЯ</h3>${state.marches.length?state.marches.map(m=>`<div class="march-row"><strong>${state.places.find(p=>p.id===m.target).name} ${m.returning?'→ столица':'← столица'}</strong><p>${totalTroops(m.troops)} воинов · ${m.battle?'Сражение':m.returning?'Возвращаются':'В пути'} · <span data-countdown="${m.end}"></span></p><div class="progress-track"><span data-progress-start="${m.start}" data-progress-end="${m.end}"></span></div></div>`).join(''):'<p class="muted">Армии в столице. Выберите на карте разбойничий стан или вражеское поселение, чтобы начать поход.</p>'}`;}
function diplomacyPanel(){if(selectedFaction)return factionPanel(selectedFaction);return `<p class="intro">Договоры приносят доход и доверие. Для союза нужна репутация 45. Нападение на деревни и нарушение пактов заставляют соседей опасаться вас.</p><div class="info-strip"><div><small>РЕПУТАЦИЯ</small><strong>${state.reputation} <em>/ 100</em></strong></div><div><small>СОЮЗЫ</small><strong>${Object.entries(state.relations).filter(([k,r])=>!r.group||r.group===k).map(([,r])=>r).filter(r=>r.status==='alliance').length} <em>/ 4</em></strong></div><div><small>ТОРГОВЫЕ ПУТИ</small><strong>${Object.entries(state.relations).filter(([k,r])=>!r.group||r.group===k).map(([,r])=>r).filter(r=>r.trade).length}</strong></div></div><div class="diplomacy-list">${state.places.filter(p=>p.owner!=='player'&&state.relations[p.id]&&(!state.relations[p.id].group||state.relations[p.id].group===p.id)).map(p=>{const r=state.relations[p.id],own=p.owner==='player';return `<div class="faction-row"><span class="settlement-crest" style="color:${p.color}">${icon(p.kind==='city'?'crown':'tree')}</span><div class="faction-name"><h3>${p.name}</h3><p>${escape(p.ruler)}${r.trade?' · Торговля +65/мин':''}</p></div><span class="tag ${r.status==='war'?'bad':r.status==='alliance'?'good':''}">${own?'ВАШИ ЗЕМЛИ':{peace:'МИР',alliance:'СОЮЗ',war:'ВОЙНА',pact:'ПАКТ'}[r.status]}</span><button class="secondary" data-negotiate="${p.id}" ${own?'disabled':''}>Переговоры</button></div>`;}).join('')}</div><h3 class="section-title">КОРОЛЕВСКИЙ РЫНОК</h3>${marketPanel()}`;}
function marketPanel(){const drought=state.events.some(e=>e.type==='drought');return `${['wood','stone','food'].map(k=>{const price=k==='food'&&drought?160:k==='stone'?130:100;return `<div class="trade-row">${icon(resourceIcons[k])}<strong>${RESOURCES[k]} · 100</strong><button class="secondary" data-trade="${k}" data-side="sell">Продать · ${Math.floor(price*.65)} ${icon('coins')}</button><button class="secondary" data-trade="${k}" data-side="buy">Купить · ${price} ${icon('coins')}</button></div>`;}).join('')}${drought?'<p class="muted danger-text">Засуха: цены на провизию выросли на 60%.</p>':''}`;}
function factionPanel(id){const p=state.places.find(p=>p.id===id),r=state.relations[id];if(!r||p.owner==='player')return '<p>Это ваше владение. Переговоры с собой недоступны.</p>';const realm=state.places.find(x=>x.id===r.group),human=!!state.realmColors?.[p.owner];const defs=[['trade','Открыть торговый путь','+65 золота / мин · +3 репутации',human?130:120,r.trade||r.status==='war'],['alliance','Предложить союз','+8 репутации · доступна военная помощь',human?180:300,r.status==='alliance'||r.status==='war'||state.reputation<45],['pact','Пакт о ненападении','Закрепить мир между державами',human?110:100,['alliance','pact','war'].includes(r.status)],['aid','Попросить военную помощь','15 копейщиков от союзника · раз в минуту',human?120:180,r.status!=='alliance'||(r.aidAt||0)>state.time],['peace','Заключить мир','Завершить войну и отозвать походы',human?160:220,r.status!=='war'],['war','Объявить войну',r.status==='pact'||r.status==='alliance'?'Нарушение договора: −25 репутации':'−8 репутации · торговля прекращается',0,r.status==='war']];return `<button class="back-button" data-diplomacy-back>← Все правители</button><div class="faction-row"><span class="settlement-crest" style="color:${p.color}">${icon('crown')}</span><div class="faction-name"><h3>${p.name}</h3><p>${escape(p.ruler)}</p></div><span class="tag ${r.status==='war'?'bad':'good'}">${{peace:'МИР',alliance:'СОЮЗ',war:'ВОЙНА',pact:'ПАКТ'}[r.status]}</span></div><p class="intro" style="margin-top:18px">${p.detail}. Оборона: ${p.defense}. Отношения с державой ${realm?.name||p.name} и правителем ${escape(p.ruler)}; договор действует для всех его земель. ${r.trade?'Между нашими землями идут караваны.':''}</p><div class="action-grid">${defs.map(([action,title,text,cost,disabled])=>`<button class="${action==='war'?'danger':'secondary'} diplomacy-action" data-diplomatic="${action}" data-target="${id}" ${disabled||p.owner==='player'?'disabled':''}><strong>${title}</strong><small>${text}</small><span class="price">${cost?`${icon('coins')} ${cost} золота`:r.status==='war'?'Война уже объявлена':'Разорвать отношения'}</span></button>`).join('')}</div>${r.status==='war'?`<button class="primary full" data-attack="${id}">${icon('swords')}Подготовить поход</button>`:''}`;}
function researchPanel(){return `<p class="intro">Каждое открытие действует на всё королевство. ${state.buildings.academy?'Учёные готовы служить вашей державе.':'Постройте академию, чтобы начать исследования.'}</p>${!state.buildings.academy?'<button class="primary" data-open="build">Перейти к строительству</button>':''}<div class="card-grid" style="margin-top:20px">${Object.entries(TECHS).map(([key,t])=>{const lv=state.techs[key],queued=state.queue.some(q=>q.type==='research');return `<article class="tech-card"><div class="card-top"><span class="card-icon">${icon(t.icon)}</span><div><h3>${t.name}</h3><small>УРОВЕНЬ ${lv} / 3</small></div></div><p>${t.text}</p>${lv<3?costs(costAt(t.cost,lv)):''}<div class="card-footer"><small>${16+lv*10} сек.</small><button class="secondary" data-research="${key}" ${lv>=3||queued||!state.buildings.academy?'disabled':''}>${lv>=3?'Изучено':'Исследовать'}</button></div></article>`;}).join('')}</div>`;}
function worldPanel(){const drought=state.events.find(e=>e.type==='drought'),invasion=state.events.find(e=>e.type==='invasion');return `<p class="intro">Мир живёт по своим правилам. Готовьте запасы, укрепляйте стены и следите за вестями.</p><article class="event-card"><div class="panel-kicker">${icon('sun')}ПРИРОДНОЕ ЯВЛЕНИЕ</div><h3 style="margin-top:12px">${drought?'Засуха в долине':state.flags.drought?'Земля снова плодородна':'Сухое лето впереди'}</h3><p>${drought?'Производство провизии снижено на 55%. Цена еды на рынке выросла.':state.flags.drought?'Дожди вернулись в Эльдорию. Урожаи и цены восстановились.':'На 4-й день наступит засуха. Запасите провизию или улучшите фермы.'}</p>${drought?`<span class="tag bad">ОСТАЛОСЬ <span data-countdown="${drought.end}"></span></span>`:''}</article><article class="event-card"><div class="panel-kicker">${icon('swords')}УГРОЗА С СЕВЕРА</div><h3 style="margin-top:12px">Варварские племена</h3><p>${state.flags.raided?'Северный набег завершён. Его исход записан в летопись.':invasion?'Варвары приближаются. Сумма силы гарнизона и стен должна быть не ниже 240.':'На 9-й день придут варвары. Они атакуют через 45 секунд после предупреждения. Нужна суммарная защита 240.'}</p>${invasion?`<span class="tag bad">ДО НАБЕГА <span data-countdown="${invasion.end}"></span></span>`:''}</article><article class="event-card"><div class="panel-kicker">${icon('flame')}ДРЕВНЯЯ СИЛА</div><h3 style="margin-top:12px">Пробуждение Камнерога</h3><p>Редкий ритуал призывает древнего зверя. Он идёт к одному из вражеских городов и разрушает 80% его обороны. Требуются святилище и объявленная война. Подготовка — 45 секунд, путь — 30 секунд.</p>${costs({gold:2500,stone:800,food:700})}${state.ritual?`<p class="effect">Ритуал идёт · <span data-countdown="${state.ritual.end}"></span></p>`:state.beast?`<p class="effect">Камнерог в пути · <span data-countdown="${state.beast.end}"></span></p>`:`<button class="primary" data-summon ${!state.buildings.shrine?'disabled':''}>${icon('flame')}Начать ритуал</button>${!state.buildings.shrine?'<p class="muted" style="margin-top:10px">Сначала постройте древнее святилище.</p>':''}`}</article>`;}
function goalsPanel(){return `<p class="intro">Военная победа: захватите столицы остальных правителей. Экономическая: накопите 6 000 золота и откройте 3 торговых пути. Политическая: получите 4 союза и репутацию 80.</p><p>Города и ресурсы общие для сетевой партии. Наём, строительство и сражения рассчитывает сервер.</p>`;}
function marchPanel(){const p=state.places.find(p=>p.id===selected),troops=Object.fromEntries(Object.entries(state.troops).map(([k,v])=>[k,Math.floor(v*fraction)])),force=power(troops,state,p),ratio=force/Math.max(1,p.defense);return `<p class="intro">Цель: <strong>${p.name}</strong>. ${p.owner==='player'?'Подкрепление усилит гарнизон этого владения.':'После боя часть выживших останется охранять захваченную землю. Остальные вернутся в столицу.'}</p><div class="inline-control"><span>Отправить часть гарнизона</span><select id="march-fraction" aria-label="Доля гарнизона в походе">${[.25,.5,.75,1].map(n=>`<option value="${n}" ${fraction===n?'selected':''}>${n*100}% · ${Object.values(state.troops).reduce((a,v)=>a+Math.floor(v*n),0)} воинов</option>`).join('')}</select></div><div class="info-strip"><div><small>СИЛА ОТРЯДА</small><strong>${force}</strong></div><div><small>${p.owner==='player'?'ЗАЩИТА ВЛАДЕНИЯ':'ОБОРОНА ВРАГА'}</small><strong>${p.defense}</strong></div><div><small>В ПУТИ</small><strong>${Math.ceil(Math.max(30,routeLength(findRoute(state.places.find(p=>p.id===(state.home||'home')),p,state.places,state.map)||[{x:0,z:0}])*1.4))} <em>сек.</em></strong></div></div><p class="battle-info">Прогноз: <strong class="${ratio<1?'danger-text':''}">${p.owner==='player'?'Усиление гарнизона':ratio>=1.7?'Уверенная победа':ratio>=1?'Победа с потерями':'Поражение — укрепите армию'}</strong>.</p><p class="intro">Сила учитывает состав армии и военные исследования. На поход нужно 40 провизии. Не оставляйте столицу без защиты во время набега.</p><p class="danger-text">В столице останется ${totalTroops(state.troops)-totalTroops(troops)} воинов. Их сила вместе со стенами защищает вас от захвата.</p>${costs({food:40})}<button class="primary full" data-march ${!totalTroops(troops)||p.id===state.home||(p.owner!=='player'&&state.relations[p.id]&&state.relations[p.id].status!=='war')?'disabled':''}>${icon('swords')}Отправить ${totalTroops(troops)} воинов</button>`;}
function helpPanel(){return '<p class="intro">Ваша цель — сохранить столицу и развить державу. Гарнизон защищает город автоматически; в поход уходят только выбранные воины.</p><div class="help-row"><b>1</b><span><strong>Улучшите ферму.</strong> Это даст больше еды для войска. Затем стройте рынок для золота.<button class="primary" data-open="build">Открыть строительство</button></span></div><div class="help-row"><b>2</b><span><strong>Начните с торговли.</strong> Выберите свободное поселение: договоры мирно увеличивают доход. Надпись «Война» относится к указанному правителю и его землям.<button class="secondary" data-tutorial-target="willow">Показать Ивовую долину</button></span></div><div class="help-row"><b>3</b><span><strong>Подготовьте армию.</strong> Наймите копейщиков, постройте стены. В окне похода сравните силу армии с обороной цели. Отправляйте не более половины гарнизона.<button class="secondary" data-open="army">Открыть армию</button></span></div><p>Чтобы захватить Ивовую долину: переговоры → объявить войну → подготовить поход. После 12-секундного боя цвет флага изменится. Часть выживших останется охранять деревню, доход придёт автоматически. Нажмите на неё, чтобы отправить подкрепление.</p><p>Первые 5 минут боты не нападают на державы игроков. При приближении врага появится предупреждение с таймером. Потеря столицы завершит ваше правление.</p><p>Исследования доступны после постройки академии: севооборот увеличивает еду, военное дело — силу, дипломатия — репутацию. Это следующий этап, а не первая задача.</p><p>Перетаскивайте карту мышью, вращайте правой кнопкой и приближайте колесом. «Комната» возвращает в зал участников. Музыка и громкость — кнопка ♫ сверху.</p><button class="secondary full" data-open="goals">Условия победы</button>';}
function updateActionState(){const status=online?.status?.();if(!status)return;document.body.classList.toggle('spectating',status.ended);document.querySelectorAll('[data-build],[data-recruit],[data-research],[data-diplomatic],[data-trade],[data-march],[data-summon],[data-recall],[data-accept],[data-reject]').forEach(el=>{if(status.ended){el.disabled=true;el.title='Правление завершено: приказы недоступны';}});}
function updateThreats(){let el=$('#threat-alert');if(!el){el=document.createElement('aside');el.id='threat-alert';el.setAttribute('role','alert');$('#game').append(el);}const threats=(state.mapMarches||[]).filter(m=>!m.returning&&m.owner!==state.realmId&&state.places.find(p=>p.id===m.target)?.owner==='player');el.hidden=!threats.length||state.eliminated||!!state.matchWinner;if(el.hidden)return;el.innerHTML='<strong>⚔ '+(threats.some(m=>m.battle)?'Сражение у ваших стен':'Вражеская армия приближается')+'</strong>'+threats.map(m=>'<p>'+escape(state.realmNames?.[m.owner]||'Противник')+' → '+state.places.find(p=>p.id===m.target).name+' · '+totalTroops(m.troops)+' воинов · '+(m.battle?'исход боя':'прибытие')+' через '+Math.max(0,Math.ceil(m.end-state.time))+' сек.</p>').join('')+'<button class="secondary" data-open="army">Усилить войско</button> <button class="secondary" data-open="build">Построить стены</button>';}
function renderPanel(){if(!currentPanel)return;const scroll=drawer.scrollTop;$('#drawer-title').textContent=titles[currentPanel]||'Королевский совет';$('#drawer-kicker').textContent=currentPanel==='world'?'ЗЕМЛИ ЭЛЬДОРИИ':currentPanel==='log'?'КАЖДОЕ РЕШЕНИЕ — ИСТОРИЯ':'КОРОЛЕВСКИЙ СОВЕТ';content.innerHTML=({build:buildPanel,army:armyPanel,diplomacy:diplomacyPanel,research:researchPanel,world:worldPanel,goals:goalsPanel,march:marchPanel,help:helpPanel,log:()=>state.logs.map(l=>`<div class="log-entry ${['good','bad'].includes(l.kind)?l.kind:''}"><span class="log-dot"></span><div><p>${escape(l.text)}</p><small>День ${Math.floor(l.time/30)+1} · ${String(Math.floor(l.time%30)*2).padStart(2,'0')} мин.</small></div></div>`).join(''),new:()=>`<div class="confirmation"><p>Начать новую игру? Вы покинете текущую сетевую комнату. Вернуться в начатую партию после выхода нельзя. Из главного меню можно создать другую партию.</p><div class="actions"><button class="primary" data-new-game>Начать заново</button><button class="secondary" data-open="help">Вернуться</button></div></div>`,victory:()=>`<div class="victory">${icon('crown')}<h3>${state.victory||'Великая держава'}</h3><p>От первого камня Велиграда до великой державы — ваши решения стали историей. День ${Math.floor(state.time/30)+1} войдёт в летопись.</p><div class="actions"><button class="primary" data-continue>Продолжить правление</button><button class="secondary" data-open="new">Новая игра</button></div></div>`}[currentPanel]||helpPanel)();if(currentPanel==='diplomacy')content.insertAdjacentHTML('afterbegin',online.offersHTML());drawer.scrollTop=scroll;updateLive();updateActionState();}
function updateLive(){document.querySelectorAll('[data-countdown]').forEach(el=>{el.textContent=`${Math.max(0,Math.ceil(Number(el.dataset.countdown)-state.time))} сек.`;});document.querySelectorAll('[data-progress-end]').forEach(el=>{const start=Number(el.dataset.progressStart),end=Number(el.dataset.progressEnd);el.style.width=`${Math.max(0,Math.min(100,(state.time-start)/(end-start)*100))}%`;});document.querySelectorAll('[data-cost-key]').forEach(el=>el.classList.toggle('short',state.resources[el.dataset.costKey]<Number(el.dataset.costValue)));}
function updateUI(force=false){const inc=income(state);$('#resources').innerHTML=Object.entries(RESOURCES).map(([key,name])=>`<div class="resource ${key}" title="${name}: ${Math.round(inc[key])} в игровую минуту">${icon(resourceIcons[key])}<div><strong>${format(state.resources[key])}</strong><small>${name}<em class="${inc[key]<0?'negative':''}">${inc[key]>=0?'+':''}${Math.round(inc[key])}/мин</em></small></div></div>`).join('');$('#day').textContent=`День ${Math.floor(state.time/30)+1}`;$('#pause').textContent=state.speed===0?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',state.speed===0?'Продолжить игру':'Пауза');document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',Number(b.dataset.speed)===state.speed));
  const steps=[state.buildings.farm>=2,state.places.find(p=>p.id==='bandits').owner==='player',Object.entries(state.relations).filter(([k,r])=>!r.group||r.group===k).map(([,r])=>r).some(r=>r.trade)];
  const objectiveHTML=`<div class="panel-kicker">${icon('crown')}НАЧАЛО ВЕЛИКОЙ ИСТОРИИ</div><h3>${steps.every(Boolean)?'Королевство крепнет':!steps[0]?'Заложите основу':!steps[2]?'Найдите союзников':'Обезопасьте земли'}</h3><p>${steps.every(Boolean)?'Первые шаги сделаны. Выберите свой путь к величию.':!steps[0]?'Улучшите ферму до II уровня, чтобы обеспечить королевство провизией.':!steps[2]?'Откройте торговый путь с соседним поселением.':'Освободите старый тракт от разбойников и получите награду.'}</p><div class="objective-progress">${steps.map(s=>`<span class="${s?'done':''}"></span>`).join('')}</div><button data-open="${steps.every(Boolean)?'goals':!steps[0]?'build':!steps[2]?'diplomacy':'army'}">${steps.every(Boolean)?'Три пути к победе':'К королевскому совету'} ${icon('arrow')}</button>`;
  if(!state.eliminated&&!state.matchWinner)setHTML($('#objective'),objectiveHTML);
  const event=state.events.find(e=>e.type==='invasion')||state.events[0];$('#world-event').innerHTML=event?`<div class="event-kicker">МИРОВОЕ СОБЫТИЕ · ${Math.ceil(event.end-state.time)} СЕК.</div><h3>${event.type==='drought'?'Засуха в долине':'Варвары у границ'}</h3><p>${event.type==='drought'?'Урожай −55%. Берегите запасы.':'Укрепляйте стены. Набег близко.'}</p>`:`<div class="event-kicker">${state.time<90?'ПЕРВАЯ ЭПОХА':'ВЕТЕР ПЕРЕМЕН'}</div><h3>${state.time<90?'Время возможностей':'Мир помнит решения'}</h3><p>${state.time<90?'Купцы ищут новые пути. Соседи пока хранят мир.':'Сила королевства — в ваших руках.'}</p>`;
  $('#latest-log').innerHTML=`<p>${escape(state.logs[0]?.text||'Летопись пуста')}</p><small>День ${Math.floor((state.logs[0]?.time||0)/30)+1}</small>`;
  $('#queue').innerHTML=state.queue.slice(0,4).map(q=>`<div class="queue-item"><div><span>${q.type==='build'?BUILDINGS[q.key].name:q.type==='recruit'?`${UNITS[q.key].name} ×${q.count}`:TECHS[q.key].name}</span><small data-countdown="${q.end}"></small></div><div class="progress-track"><span data-progress-start="${q.start}" data-progress-end="${q.end}"></span></div></div>`).join('');
  const fingerprint=JSON.stringify([state.buildings,state.troops,state.techs,state.queue.length,state.marches.map(m=>[m.id,m.returning]),state.relations,state.places.map(p=>[p.owner,p.defense]),state.events.map(e=>e.type),!!state.ritual,!!state.beast,state.reputation,state.victory]);
  if(force||fingerprint!==previousFingerprint){previousFingerprint=fingerprint;updateSelection();if(currentPanel)renderPanel();drawMinimap();}
  if(lastLog!==state.logs[0]?.text){lastLog=state.logs[0]?.text;if(state.logs[0]?.kind==='bad'){toast(lastLog,true);sound.cue('warning');}else if(/готов|прибыли|Победа/.test(lastLog||'')){toast(lastLog);sound.cue('build');}if(currentPanel==='log')renderPanel();}
  updateThreats();updateActionState();
  if(state.eliminated||state.matchWinner){$('#objective').innerHTML=`<div class="panel-kicker">${state.matchWinner?'ПАРТИЯ ЗАВЕРШЕНА':'СТОЛИЦА ПОТЕРЯНА'}</div><h3>${state.matchWinner?escape(state.matchWinner.name):'Ваше правление завершено'}</h3><p>${state.matchWinner?state.matchWinner.type:'Вы можете наблюдать за оставшимися правителями.'}</p>`;}updateLive();if(state.victory&&currentPanel!=='victory'&&currentPanel!=='new')openPanel('victory');
}
function drawMinimap(){const canvas=$('#minimap'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#344d39';ctx.fillRect(0,0,w,h);const x=v=>(v+42)/84*w,z=v=>(v+36)/72*h;ctx.strokeStyle='#73a3a2';ctx.lineWidth=8;ctx.beginPath();for(let i=-36;i<=36;i++){const px=x(riverX(i,state.map)),pz=z(i);i===-36?ctx.moveTo(px,pz):ctx.lineTo(px,pz);}ctx.stroke();ctx.fillStyle='#273f2d';for(let i=0;i<45;i++){const px=(Math.sin(i*13.71)*.5+.5)*w,pz=(Math.sin(i*4.91)*.5+.5)*h;ctx.beginPath();ctx.arc(px,pz,3+i%4,0,Math.PI*2);ctx.fill();}for(const p of state.places){ctx.fillStyle=p.owner==='player'?'#91d1aa':p.color;ctx.fillRect(x(p.x)-3,z(p.z)-3,6,6);if(p.id===selected){ctx.strokeStyle='#f2dd9d';ctx.lineWidth=1;ctx.strokeRect(x(p.x)-6,z(p.z)-6,12,12);}}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
  if(b.dataset.panel)openPanel(b.dataset.panel);
  else if(b.dataset.open)openPanel(b.dataset.open);
  else if(b.dataset.build)perform('build',{key:b.dataset.build});
  else if(b.dataset.recruit)perform('recruit',{key:b.dataset.recruit,count:recruitCount});
  else if(b.dataset.research)perform('research',{key:b.dataset.research});
  else if(b.dataset.negotiate)openPanel('diplomacy',{faction:b.dataset.negotiate});
  else if(b.hasAttribute('data-diplomacy-back')){selectedFaction=null;renderPanel();}
  else if(b.dataset.diplomatic)perform('diplomacy',{target:b.dataset.target,action:b.dataset.diplomatic});
  else if(b.dataset.trade)perform('trade',{resource:b.dataset.trade,side:b.dataset.side});
  else if(b.dataset.filter){unitFilter=b.dataset.filter;renderPanel();}
  else if(b.dataset.attack){selectPlace(b.dataset.attack);openPanel('march');}
  else if(b.hasAttribute('data-march')){if((await perform(state.places.find(p=>p.id===selected).owner==='player'?'reinforce':'march',{target:selected,fraction})).ok)closePanel();}
  else if(b.dataset.recall)perform('recall',{target:b.dataset.recall});
  else if(b.dataset.tutorialTarget){selectPlace(b.dataset.tutorialTarget);world?.focus(b.dataset.tutorialTarget);openPanel('diplomacy',{faction:b.dataset.tutorialTarget});}
  else if(b.hasAttribute('data-summon'))perform('summon');
  else if(b.hasAttribute('data-new-game')){await online.leave();}
  else if(b.hasAttribute('data-continue')){closePanel();}
  else if(b.dataset.speed){toast('В сетевой партии время общее');}
});
document.addEventListener('change',e=>{if(e.target.id==='recruit-count'){recruitCount=Number(e.target.value);renderPanel();}if(e.target.id==='march-fraction'){fraction=Number(e.target.value);renderPanel();}});
$('#close-drawer').onclick=closePanel;drawer.addEventListener('cancel',e=>{e.preventDefault();closePanel();});drawer.addEventListener('click',e=>{if(e.target===drawer){const r=drawer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel();}});
$('#help').onclick=()=>openPanel('help');$('#show-log').onclick=()=>openPanel('log');$('#brand').onclick=()=>{selectPlace(state.home||'home');world?.focus(state.home||'home');};$('#reset-camera').onclick=()=>{selectPlace(state.home||'home');world?.focus(state.home||'home');};$('#zoom-in').onclick=()=>world?.zoom(.84);$('#zoom-out').onclick=()=>world?.zoom(1.18);$('#borders').onclick=()=>{const show=$('#borders').getAttribute('aria-pressed')!=='true';$('#borders').setAttribute('aria-pressed',String(show));$('#borders').classList.toggle('active',show);world?.borders(show);};
function togglePause(){toast('В сетевой партии пауза отключена');}$('#pause').onclick=togglePause;
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.code==='Space'){e.preventDefault();togglePause();}if(['1','2','3','4','5'].includes(e.key))openPanel(['build','army','diplomacy','research','world'][Number(e.key)-1]);});
$('#minimap').onclick=e=>{const r=e.currentTarget.getBoundingClientRect(),mx=(e.clientX-r.left)/r.width*84-42,mz=(e.clientY-r.top)/r.height*72-36;const nearest=[...state.places].sort((a,b)=>Math.hypot(a.x-mx,a.z-mz)-Math.hypot(b.x-mx,b.z-mz))[0];selectPlace(nearest.id);world?.focus(nearest.id);};
window.addEventListener('pagehide',save);
let online;online=connectOnline({receive(snapshot,meta){const start=!state.online;state=snapshot;state.receivedAt=performance.now();state.online=true;if(start){selected=state.home;world?.dispose();$('#world').replaceChildren();$('#labels').replaceChildren();world=createWorld($('#world'),$('#labels'),()=>state,selectPlace);world.select(selected);world.focus(selected);}updateUI(start);if(start&&!state.eliminated&&!state.matchWinner)openPanel('help');},toast});
updateUI(true);
try{world=createWorld($('#world'),$('#labels'),()=>state,selectPlace);setTimeout(()=>{$('#loading').classList.add('finished');setTimeout(()=>$('#loading').remove(),700);},350);}catch(error){console.error(error);$('#loading').classList.add('error');$('#loading').innerHTML=`${icon('crown')}<h2>Карта не загрузилась</h2><p class="no-webgl">Для 3D-карты нужен WebGL 2. Откройте игру в современном Chrome, Edge или Firefox с включённым аппаратным ускорением.</p><button class="primary" id="retry">Попробовать ещё раз</button>`;$('#retry').onclick=()=>location.reload();}
let last=performance.now(),uiAt=0,saveAt=0;
function loop(now){const dt=Math.min(.25,(now-last)/1000);last=now;if(now-uiAt>500){updateUI();uiAt=now;}if(now-saveAt>5000){save();saveAt=now;}requestAnimationFrame(loop);}requestAnimationFrame(loop);
document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden)save();});
// Browser agents use the same validated rules as the visible controls.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
  register({name:'read_kingdom',title:'Состояние королевства',description:'Read resources, buildings, troops, diplomacy and active marches in the current online game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({day:Math.floor(state.time/30)+1,resources:{...state.resources},buildings:{...state.buildings},troops:{...state.troops},reputation:state.reputation,places:state.places.map(p=>({id:p.id,name:p.name,owner:p.owner,defense:p.defense})),relations:structuredClone(state.relations),queue:structuredClone(state.queue),marches:structuredClone(state.marches)})});
  register({name:'start_building',title:'Построить или улучшить здание',description:'Spend game resources and start building or upgrading one building in the capital.',inputSchema:{type:'object',properties:{building:{type:'string',enum:Object.keys(BUILDINGS)}},required:['building'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.building!=='string'||!BUILDINGS[input.building]||Object.keys(input).some(k=>k!=='building'))throw new Error('Invalid building');return perform('build',{key:input.building});}});
  register({name:'start_military_march',title:'Отправить армию',description:'Send a fraction of the garrison to a hostile target; war must already be declared for independent states.',inputSchema:{type:'object',properties:{target:{type:'string'},fraction:{type:'number',enum:[.25,.5,.75,1]}},required:['target','fraction'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.target!=='string'||![.25,.5,.75,1].includes(input.fraction)||Object.keys(input).some(k=>!['target','fraction'].includes(k)))throw new Error('Invalid march');return perform('march',input);}});
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}





